import{_ as n,l as p,o as a,c as l,v as t,p as s,x as r,d as i,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Megatron-DeepSpeed","description":"","frontmatter":{"title":"Megatron-DeepSpeed","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/megatron-deepspeed.md","filePath":"llm/megatron-deepspeed.md","lastUpdated":1789023840000}'),g={name:"llm/megatron-deepspeed.md"};function c(m,e,B,D,P,E){const o=p("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="megatron-deepspeed" tabindex="-1">Megatron-DeepSpeed <a class="header-anchor" href="#megatron-deepspeed" aria-label="Permalink to &quot;Megatron-DeepSpeed&quot;">​</a></h1><div class="epigraph"><p>张量切分擅长节点内 NVLink，流水线擅长跨机点对点，数据并行擅长把副本铺到上千卡；三轴一起编，才能放下 5300 亿的稠密 Transformer。</p><footer>—— Smith 等，Megatron-Turing NLG 530B，arXiv:2201.11990</footer></div><p><strong>Megatron-DeepSpeed</strong> 指微软与 NVIDIA 把 <a href="/llm/megatron-lm">Megatron-LM</a> 的张量切分和 DeepSpeed 的流水线、数据并行（含 <a href="/llm/zero-stages">ZeRO</a>）焊成同一套运行时。公开证据有两条要分开：一是 2021–2022 年合训的稠密解码器 <strong>Megatron-Turing NLG 530B（MT-NLG）</strong>，论文 2201.11990；二是 GitHub 仓库 <code>microsoft/Megatron-DeepSpeed</code>，后来也被 BigScience 等用来训 BLOOM 一类开源大模型。本篇以 530B 论文讲 <strong>3D 并行</strong> 的工程语义，仓库功能（课程学习、MoE 等）只标「实现里有、论文未逐项当主结果」——不为仓库里每一项功能伪造 arXiv。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>5300 亿参数、混合精度 Adam，论文按约 20 字节/参数计，光权重、梯度与优化器状态就超过 <strong>10 TB</strong>；激活若按整 batch 驻留再加约 16.9 TB。单靠数据并行会复制整模；单靠张量并行跨节点通信太密；单靠流水线则微批与气泡、以及单层仍然太大。需要一张拓扑：哪些集合通信走 NVLink，哪些走 InfiniBand，以及 batch 大到 1920 时如何用微批把峰值激活打下来。</p><p>第二问是质量与稳定。千卡上的损失尖峰、数据清洗与偏见，和并行度同样决定「这个 530B 能不能当研究基线」。论文因此用整节写语料、社会偏见与 in-context 学习，而不是只报 TFLOP/s。</p><h3 id="三维各管一段效率" tabindex="-1">三维各管一段效率 <a class="header-anchor" href="#三维各管一段效率" aria-label="Permalink to &quot;三维各管一段效率&quot;">​</a></h3><ul><li><strong>张量并行（Megatron）</strong>：层内切矩阵，省单层显存，通信是每层 All-Reduce，必须 <strong>节点内 8 路</strong>（一张 DGX 的 NVLink）。</li><li><strong>流水线并行（DeepSpeed 侧实现）</strong>：切层深，阶段间点对点传边界激活，适合 <strong>跨节点</strong>。530B 用 <strong>35 路</strong> 流水线。</li><li><strong>数据并行 + ZeRO</strong>：副本间切优化器状态等，用来把「一个 280 卡的模型副本」再复制到成百上千卡。</li></ul><p>一个 530B 副本 = 8 路 TP × 35 路 PP = <strong>280 张 A100</strong>。再在 Selene / Azure NDv4 上用 DP 扩到更多节点。全局 batch <strong>1920</strong>，序列 2048。拓扑感知放置：把高频通信钉在最近的互连上，尤其避免 DP 的梯度同步走过最差的跳。</p><p><span class="marginnote">280 卡是「一份模型」不是「一次作业的全部卡」。作业规模是副本数 × 280。把 280 写成「只用 280 卡训完 530B」是把副本和集群混了。论文还强调稀疏 MoE 可以有更多总参数，但参数效率是否可比当时不清楚，故 MT-NLG 走稠密。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型：左到右 Transformer 解码器，<strong>105 层</strong>，隐藏 <strong>20480</strong>，<strong>128</strong> 头，序列 2048。学习率 \\(5\\times 10^{-5}\\)，10 亿 token 线性预热，余弦在 3400 亿 token 量级降到 10%；前 120 亿 token 把 batch 从 32 爬到 1920。Adam \\(\\beta_2=0.95\\)，梯度裁剪 1.0，weight decay 0.1。微批把峰值激活从数十 TB 量级打到个位数 GB 量级（论文例子：1920 微批相对「一个大微批」）。Selene 上 280/350/420 台 DGX A100、batch 1920 时，迭代约 60.1 / 50.2 / 44.4 秒，对应每卡约 126 / 121 / 113 TFLOP/s——扩卡后每卡效率略降，总吞吐仍升。</p><p>仓库侧把上述 3D 编成可配置网格，并接入 DeepSpeed 的 ZeRO、激活检查点、流水线调度。BLOOM 等公开训练日志表明这套栈能在异地多实验室协作；那是工程复用，不是 2201.11990 的实验章节。</p>',13)),(a(),s(h,null,{default:r(()=>[d(o,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E5%85%A8%E5%B1%80%20batch%201920%22%5D%20--%3E%20DP%5B%22%E6%95%B0%E6%8D%AE%E5%B9%B6%E8%A1%8C%20%C3%97%20ZeRO%22%5D%0A%20%20DP%20--%3E%20PP%5B%2235%20%E8%B7%AF%E6%B5%81%E6%B0%B4%E7%BA%BF%E8%B7%A8%E8%8A%82%E7%82%B9%22%5D%0A%20%20PP%20--%3E%20TP%5B%228%20%E8%B7%AF%E5%BC%A0%E9%87%8F%E5%88%87%E5%88%86%E5%9C%A8%20NVLink%22%5D%0A%20%20TP%20--%3E%20L%5B%22%E5%8D%95%E5%8D%A1%E5%86%85%E6%A0%B8%22%5D%0A%20%20PP%20--%3E%20ACT%5B%22%E9%98%B6%E6%AE%B5%E8%BE%B9%E7%95%8C%E6%BF%80%E6%B4%BB%E7%82%B9%E5%AF%B9%E7%82%B9%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h3 id="微批、激活与「看似矛盾的大-batch」" tabindex="-1">微批、激活与「看似矛盾的大 batch」 <a class="header-anchor" href="#微批、激活与「看似矛盾的大-batch」" aria-label="Permalink to &quot;微批、激活与「看似矛盾的大 batch」&quot;">​</a></h3><p>大 batch 提高算术强度、摊通信；太大又伤泛化。论文的解是：优化器看见的全局 batch 可以很大，但流水线里流动的是微批，峰值激活跟微批走。梯度在微批上累积，等价于大 batch SGD，内存却像小 batch。这与 GPipe 的 batch splitting 同类，但叠在 TP+ZeRO 上之后，每一层的分片激活更小，调度参数（微批数、流水线度）要一起扫，不能只抄 35 和 8。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>3D 正交的意思是三组进程网格：<a href="/llm/tensor-parallel">张量并行</a> 组做层内 All-Reduce，<a href="/llm/pipeline-parallel">流水线</a> 组做发送/接收，数据并行组做梯度同步或 ZeRO 的 Reduce-Scatter/All-Gather。映射一旦把 TP 跨到 IB，每层通信延迟会吃掉 GEMM。35 路 PP 的气泡要用足够微批填；微批太多则流水线气泡小、但步内串行段变长、也可能改变数值（Dropout 粒度）。ZeRO 把 20 字节/参数的副本切薄，使 105×20480 的优化器状态能按 DP 度摊。</p><p>吞吐数字随节点数下降，说明通信与流水线气泡开始占更大比例——这是扩展曲线，不是实现回归。105 层被 35 段切，平均约 3 层一段，段间负载若不平衡，整条管道被最慢段钉住。128 头与 8 路 TP 整除，按头切干净。</p><p><span class="marginnote">MT-NLG 权重并未像 Llama 那样成为默认开源底座；论文的贡献首先是「稠密 530B 如何训得动」与评测/偏见分析。引用系统时写 3D 并行与 280 卡副本，不要暗示可以 wget 一份 530B 聊天模型。</span></p><h3 id="和纯-megatron、纯-deepspeed、alpa" tabindex="-1">和纯 Megatron、纯 DeepSpeed、Alpa <a class="header-anchor" href="#和纯-megatron、纯-deepspeed、alpa" aria-label="Permalink to &quot;和纯 Megatron、纯 DeepSpeed、Alpa&quot;">​</a></h3><p>只用 NVIDIA Megatron Core 也能 3D（2021 年后的 Megatron 已含 PP）。Megatron-DeepSpeed 的历史意义是 <strong>当时</strong> 把 DeepSpeed 的 PP/ZeRO 与 Megatron TP 接上，并真训到 530B。纯 DeepSpeed 没有 Megatron 那套对 Transformer 最友好的列/行切分细节。 <a href="/llm/alpa">Alpa</a> 用编译器搜层间/层内方案，目标是少手写网格；MT-NLG 是手写网格的高峰实例。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>2201.11990 的 SOTA 零/少样本是 2022 年初对照，稠密 530B 很快被更小但数据更多的模型在公开榜上追上。序列 2048 不是长上下文模型。论文的社会偏见章节说明放大不自动消除刻板印象。仓库与论文功能集不完全相等：看到 MoE、curriculum 要以对应 DeepSpeed/Megatron 文档为准，不要全部算进 530B 正文。</p><p>检查点与 8×35 网格绑定。混合精度下的损失缩放、流水线 flush 与 ZeRO 聚集顺序都会改数值，多实验室复现 BLOOM 时这些是真实故障源。不要把「3D 并行」写成 DeepSpeed 独创或 Megatron 独创——是组合。</p><h3 id="爬-batch-与余弦终点是稳定旋钮" tabindex="-1">爬 batch 与余弦终点是稳定旋钮 <a class="header-anchor" href="#爬-batch-与余弦终点是稳定旋钮" aria-label="Permalink to &quot;爬 batch 与余弦终点是稳定旋钮&quot;">​</a></h3><p>前 120 亿 token 把全局 batch 从 32 爬到 1920，与后来 Falcon 2 一类「中途加倍 batch 压尖峰」是同一家族：小 batch 噪声大，巨模初期更容易炸。余弦在 3400 亿 token 量级落到峰值的 10%，意味着论文并没有把「数据吃完」写成无限平台。语料清洗被作者当成质量的关键配料，与 3D 并行并列——只复制 8×35 网格、用脏网页硬训，得不到 MT-NLG 表上的零样本。Selene 与 Azure NDv4 的 A100+HDR IB 是实验平台；换到带宽更差的以太网，35 路 PP 的点对点与 DP 梯度同步都会重新成为瓶颈，需要减 PP 或加梯度累积来摊通信，而不是坚持 280 卡副本形状。</p><p><span class="marginnote">真实编号：Smith 等 <em>Using DeepSpeed and Megatron to Train Megatron-Turing NLG 530B</em>，arXiv:2201.11990。ZeRO 本体是 Rajbhandari 等 arXiv:1910.02054。Megatron 切分是 1909.08053。禁止给 <code>Megatron-DeepSpeed</code> 仓库本身编造论文号。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Megatron-DeepSpeed 把 Megatron 张量切分与 DeepSpeed 流水线/数据并行合成 3D 并行。</li><li>MT-NLG 530B：105 层、\\(d=20480\\)、128 头；副本 8-TP × 35-PP = 280 A100。</li><li>微批降低激活峰值；拓扑感知映射保护 NVLink 上的 TP。</li><li>出处：Smith 等，arXiv:2201.11990，2022；实现另见 microsoft/Megatron-DeepSpeed。</li></ul>',16))])}const A=n(g,[["render",c]]);export{u as __pageData,A as default};
